/*
 * Builds the request sent to Claude. The review is data, never an instruction: it sits between
 * tags and the system prompt forbids obeying anything it contains.
 *
 * No temperature parameter: it is deprecated on recent models and the API answers 400.
 *
 * Two rules that hold for any public reply to a review, and that are in the prompt: never reveal
 * anything about the person (dates, amounts, order number), and never promise a refund or a
 * gesture of compensation in public.
 *
 * Every sentence a person reads comes from the settings node, so the same code serves any language.
 */
const r = $('Settings').first().json;
// The Webhook node files the payload under .body; a direct call from another workflow does not.
// Both shapes are accepted, otherwise the review arrives empty and the model answers beside it.
const payload = $json.body || $json;

function pick(obj, names) {
  for (const wanted of names) {
    for (const k of Object.keys(obj || {})) {
      if (k.toLowerCase().replace(/[^a-z]/g, '') === wanted) {
        const v = obj[k];
        if (typeof v === 'string' && v.trim()) return v.trim();
        if (typeof v === 'number') return String(v);
      }
    }
  }
  return '';
}


function fill(tpl, vars) {
  return String(tpl === undefined || tpl === null ? '' : tpl)
    .replace(/\{\{\s*([a-zA-Z_]+)\s*\}\}/g, function (m, k) {
      return vars[k] === undefined || vars[k] === null ? '' : String(vars[k]);
    });
}

const author = pick(payload, ['auteur', 'author', 'nom', 'name', 'prenom', 'firstname', 'pseudo']);
const text = pick(payload, ['texte', 'text', 'avis', 'review', 'commentaire', 'comment', 'message', 'body']);
const ratingRaw = pick(payload, ['note', 'rating', 'score', 'etoiles', 'stars']);
const rating = Number(ratingRaw);
const positive = Number.isFinite(rating) ? rating >= 4 : null;

const system = fill(r.prompt_system, {
  business_name: r.business_name,
  signature: r.signature,
  max_words: r.max_words,
});
const question = fill(r.prompt_review, {
  rating: Number.isFinite(rating) ? ratingRaw : r.rating_unknown,
  author: author || r.author_unknown,
  review: String(text).slice(0, 3000),
});

return [{ json: { review: { author: author, rating: ratingRaw, text: text }, positive: positive, request: {
  model: r.model,
  max_tokens: 400,
  system: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }],
  messages: [{ role: 'user', content: question }],
} } }];

/*
 * Reads the draft and runs three deterministic checks before it reaches you:
 *   1. length
 *   2. no phrase that promises a gesture of compensation in public
 *   3. no number that looks like an amount or a date, so no detail about the person
 * A draft that fails is still sent to you, with the reason: you are the one who publishes, the
 * guardrail is there to make you read it, not to block it.
 */
const r = $('Settings').first().json;

function fill(tpl, vars) {
  return String(tpl === undefined || tpl === null ? '' : tpl)
    .replace(/\{\{\s*([a-zA-Z_]+)\s*\}\}/g, function (m, k) {
      return vars[k] === undefined || vars[k] === null ? '' : String(vars[k]);
    });
}

// Phrases, not single words: "the wifi is free" is ordinary information in a public reply, while
// "a free night for you" is a commercial promise. The first draft of this list held "free" on its
// own and flagged replies that were perfectly correct.
const blocked = String(r.blocked_phrases || '').split(',')
  .map(function (p) { return p.trim().toLowerCase(); }).filter(Boolean);

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const src = $('Build the prompt').all()[i].json;
  let text = '', failure = null;
  try {
    const body = items[i].json;
    if (body.error) throw new Error(body.error.message || JSON.stringify(body.error));
    text = (body.content || []).filter(function (b) { return b.type === 'text'; })
      .map(function (b) { return b.text; }).join('\n').trim();
    if (!text) throw new Error('empty answer from the model');
  } catch (e) {
    failure = String(e && e.message ? e.message : e);
  }

  const alerts = [];
  if (failure) alerts.push(fill(r.alert_failed, { error: failure }));
  const words = text.split(/\s+/).filter(Boolean).length;
  if (words > Number(r.max_words)) alerts.push(fill(r.alert_too_long, { words: words, max: r.max_words }));
  const low = text.toLowerCase();
  for (const phrase of blocked) {
    if (low.includes(phrase)) { alerts.push(fill(r.alert_blocked, { phrase: phrase })); break; }
  }
  if (/\b\d{1,2}[\/.]\d{1,2}[\/.]\d{2,4}\b|\b\d+\s?(€|eur|euros?|\$|usd|£|gbp)\b/i.test(text)) {
    alerts.push(r.alert_number);
  }

  out.push({ json: {
    author: src.review.author || '',
    rating: src.review.rating || '',
    review: src.review.text || '',
    draft: text,
    alerts: alerts,
    to_read: alerts.length > 0,
    subject: fill(r.email_subject, {
      flag: alerts.length ? r.subject_flag : '',
      author: src.review.author || r.author_unknown,
    }),
    text: fill(r.email_body, {
      author: src.review.author || r.author_unknown,
      rating: src.review.rating || r.rating_unknown,
      review: src.review.text || '',
      draft: text || r.draft_missing,
      alerts: alerts.length ? r.alerts_intro + alerts.join(' ; ') : r.alerts_none,
      site_link: r.site_link,
    }),
  } });
}
return out;
